-- Design contract only. NOT an automatic migration for the v0.2 runtime database.
PRAGMA foreign_keys = ON;
BEGIN;
CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE workspaces(id TEXT NOT NULL PRIMARY KEY, name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE projects(id TEXT NOT NULL PRIMARY KEY, workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, name TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE roots(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, display_name TEXT NOT NULL, canonical_uri TEXT NOT NULL, path_key TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), UNIQUE(project_id,id), UNIQUE(project_id,path_key));
CREATE TABLE project_languages(project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, language TEXT NOT NULL CHECK(language IN ('python','html')), PRIMARY KEY(project_id,language));
CREATE TABLE files(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL, root_id TEXT NOT NULL, relative_path TEXT NOT NULL CHECK(length(relative_path)>0), path_key TEXT NOT NULL, language TEXT NOT NULL CHECK(language IN ('python','html')), byte_size INTEGER NOT NULL CHECK(byte_size>=0), content_hash TEXT NOT NULL CHECK(length(content_hash)=64), state TEXT NOT NULL DEFAULT 'active' CHECK(state IN ('active','missing','ignored','too_large')), indexed_at TEXT, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), UNIQUE(project_id,id), UNIQUE(root_id,path_key), FOREIGN KEY(project_id,root_id) REFERENCES roots(project_id,id) ON DELETE CASCADE);
CREATE TABLE terms(id TEXT NOT NULL PRIMARY KEY, project_id TEXT REFERENCES projects(id) ON DELETE CASCADE, scope_key TEXT NOT NULL, key TEXT NOT NULL, key_normalized TEXT NOT NULL, title TEXT NOT NULL, definition TEXT NOT NULL, example TEXT NOT NULL DEFAULT '', language TEXT NOT NULL CHECK(language IN ('python','html','general')), source TEXT NOT NULL CHECK(source IN ('builtin','custom')), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), CHECK(scope_key=coalesce(project_id,'builtin')), CHECK((source='builtin' AND project_id IS NULL) OR (source='custom' AND project_id IS NOT NULL)), UNIQUE(scope_key,key_normalized,language));
CREATE TABLE term_aliases(term_id TEXT NOT NULL REFERENCES terms(id) ON DELETE CASCADE, alias TEXT NOT NULL, alias_normalized TEXT NOT NULL, PRIMARY KEY(term_id,alias_normalized));
CREATE TABLE annotations(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL, file_id TEXT NOT NULL, start_line INTEGER NOT NULL CHECK(start_line>=0), start_column INTEGER NOT NULL CHECK(start_column>=0), end_line INTEGER NOT NULL CHECK(end_line>=start_line), end_column INTEGER NOT NULL CHECK(end_column>=0), start_offset INTEGER NOT NULL CHECK(start_offset>=0), end_offset INTEGER NOT NULL CHECK(end_offset>start_offset), selected_text TEXT NOT NULL CHECK(length(selected_text)>0), code_hash TEXT NOT NULL CHECK(length(code_hash)=64), file_hash TEXT NOT NULL CHECK(length(file_hash)=64), content TEXT NOT NULL CHECK(length(content)>0 AND length(content)<=10000), author_label TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('active','stale','missing')), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(end_line>start_line OR end_column>start_column), UNIQUE(project_id,id), FOREIGN KEY(project_id,file_id) REFERENCES files(project_id,id) ON DELETE CASCADE);
CREATE INDEX annotations_file ON annotations(project_id,file_id,status);
CREATE TABLE annotation_tags(annotation_id TEXT NOT NULL REFERENCES annotations(id) ON DELETE CASCADE, tag TEXT NOT NULL, PRIMARY KEY(annotation_id,tag));
CREATE TABLE region_rules(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL, layer TEXT NOT NULL CHECK(layer IN ('route','business','data','ui','utility')), match_type TEXT NOT NULL CHECK(match_type IN ('path','regex','ast')), pattern TEXT NOT NULL, priority INTEGER NOT NULL DEFAULT 0, enabled INTEGER NOT NULL DEFAULT 1 CHECK(enabled IN (0,1)), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0));
CREATE TABLE jobs(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN ('index','health','map','graph','sandbox','kb_sync')), state TEXT NOT NULL CHECK(state IN ('queued','running','succeeded','failed','cancelled')), progress REAL NOT NULL DEFAULT 0 CHECK(progress>=0 AND progress<=1), request_key TEXT, input_hash TEXT, error_code TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(project_id,request_key), UNIQUE(project_id,id));
CREATE TABLE health_issues(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL, file_id TEXT NOT NULL, file_hash TEXT NOT NULL CHECK(length(file_hash)=64), type TEXT NOT NULL CHECK(type IN ('long_function','deep_nesting','duplicate_code','unused_variable','long_params','accessibility')), start_line INTEGER NOT NULL CHECK(start_line>=0), end_line INTEGER NOT NULL CHECK(end_line>=start_line), message TEXT NOT NULL, suggestion TEXT NOT NULL, rule_version TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('open','ignored','obsolete')), created_at TEXT NOT NULL, FOREIGN KEY(project_id,file_id) REFERENCES files(project_id,id) ON DELETE CASCADE);
CREATE INDEX health_by_file ON health_issues(project_id,file_id,status);
ALTER TABLE health_issues ADD COLUMN version INTEGER NOT NULL DEFAULT 1 CHECK(version>0);
CREATE TABLE diagnostics(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL, file_id TEXT NOT NULL, file_hash TEXT NOT NULL CHECK(length(file_hash)=64), provider TEXT NOT NULL, original_message TEXT NOT NULL, translated_message TEXT NOT NULL, start_line INTEGER NOT NULL CHECK(start_line>=0), start_column INTEGER NOT NULL CHECK(start_column>=0), UNIQUE(project_id,id), FOREIGN KEY(project_id,file_id) REFERENCES files(project_id,id) ON DELETE CASCADE);
CREATE TABLE fix_previews(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL, diagnostic_id TEXT NOT NULL, file_id TEXT NOT NULL, base_hash TEXT NOT NULL CHECK(length(base_hash)=64), document_version INTEGER NOT NULL CHECK(document_version>=0), edits_json TEXT NOT NULL, state TEXT NOT NULL CHECK(state IN ('previewed','applied','expired','rejected')), expires_at TEXT NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(project_id,diagnostic_id) REFERENCES diagnostics(project_id,id) ON DELETE CASCADE, FOREIGN KEY(project_id,file_id) REFERENCES files(project_id,id) ON DELETE CASCADE);
CREATE TABLE fix_history(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, file_id TEXT, preview_id TEXT, title TEXT NOT NULL, applied_at TEXT NOT NULL, saved INTEGER NOT NULL DEFAULT 0 CHECK(saved IN (0,1)));
CREATE TABLE flow_graphs(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN ('dependency','call','data')), input_hash TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(project_id,id));
CREATE TABLE flow_nodes(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL, graph_id TEXT NOT NULL, file_id TEXT, type TEXT NOT NULL CHECK(type IN ('file','function','class','external')), label TEXT NOT NULL, line INTEGER CHECK(line>=0), evidence_json TEXT NOT NULL DEFAULT '{}', UNIQUE(project_id,graph_id,id), FOREIGN KEY(project_id,graph_id) REFERENCES flow_graphs(project_id,id) ON DELETE CASCADE, FOREIGN KEY(project_id,file_id) REFERENCES files(project_id,id) ON DELETE CASCADE);
CREATE TABLE flow_edges(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL, graph_id TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, relation_type TEXT NOT NULL CHECK(relation_type IN ('imports','calls','inherits','contains','requests')), confidence REAL NOT NULL CHECK(confidence>=0 AND confidence<=1), evidence_json TEXT NOT NULL, UNIQUE(graph_id,source_id,target_id,relation_type), FOREIGN KEY(project_id,graph_id,source_id) REFERENCES flow_nodes(project_id,graph_id,id) ON DELETE CASCADE, FOREIGN KEY(project_id,graph_id,target_id) REFERENCES flow_nodes(project_id,graph_id,id) ON DELETE CASCADE);
CREATE TABLE guide_paths(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), UNIQUE(project_id,id));
CREATE TABLE guide_steps(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL, guide_id TEXT NOT NULL, file_id TEXT NOT NULL, position INTEGER NOT NULL CHECK(position>=0), symbol_name TEXT, line INTEGER NOT NULL CHECK(line>=0), description TEXT NOT NULL, UNIQUE(guide_id,position), FOREIGN KEY(project_id,guide_id) REFERENCES guide_paths(project_id,id) ON DELETE CASCADE, FOREIGN KEY(project_id,file_id) REFERENCES files(project_id,id) ON DELETE CASCADE);
CREATE TABLE knowledge_entities(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('file','function','term','concept')), name TEXT NOT NULL, file_id TEXT, term_id TEXT REFERENCES terms(id) ON DELETE CASCADE, summary TEXT NOT NULL, provenance TEXT NOT NULL CHECK(provenance IN ('parser','human','model')), confidence REAL NOT NULL CHECK(confidence>=0 AND confidence<=1), UNIQUE(project_id,id), FOREIGN KEY(project_id,file_id) REFERENCES files(project_id,id) ON DELETE CASCADE);
CREATE TABLE knowledge_relations(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL, source_id TEXT NOT NULL, target_id TEXT NOT NULL, relation_type TEXT NOT NULL CHECK(relation_type IN ('calls','depends_on','reads','writes','validates','related')), evidence_json TEXT NOT NULL, confidence REAL NOT NULL CHECK(confidence>=0 AND confidence<=1), UNIQUE(project_id,source_id,target_id,relation_type), FOREIGN KEY(project_id,source_id) REFERENCES knowledge_entities(project_id,id) ON DELETE CASCADE, FOREIGN KEY(project_id,target_id) REFERENCES knowledge_entities(project_id,id) ON DELETE CASCADE);
CREATE TABLE embeddings(entity_id TEXT NOT NULL REFERENCES knowledge_entities(id) ON DELETE CASCADE, model_id TEXT NOT NULL, dimension INTEGER NOT NULL CHECK(dimension>0), input_hash TEXT NOT NULL CHECK(length(input_hash)=64), vector_blob BLOB NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY(entity_id,model_id));
CREATE TABLE kb_entries(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, type TEXT NOT NULL CHECK(type IN ('annotation','explanation','diagram')), title TEXT NOT NULL, relative_path TEXT NOT NULL, content_hash TEXT NOT NULL CHECK(length(content_hash)=64), version INTEGER NOT NULL DEFAULT 1 CHECK(version>0), updated_at TEXT NOT NULL, UNIQUE(project_id,relative_path));
CREATE TABLE kb_tags(entry_id TEXT NOT NULL REFERENCES kb_entries(id) ON DELETE CASCADE, tag TEXT NOT NULL, PRIMARY KEY(entry_id,tag));
CREATE TABLE chat_sessions(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, provider TEXT NOT NULL CHECK(provider IN ('local','cloud')), model_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE chat_messages(id TEXT NOT NULL PRIMARY KEY, session_id TEXT NOT NULL REFERENCES chat_sessions(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('user','assistant')), content TEXT NOT NULL, citations_json TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL);
CREATE TABLE consent_records(id TEXT NOT NULL PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE, purpose TEXT NOT NULL CHECK(purpose IN ('ai_local','ai_cloud')), payload_hash TEXT NOT NULL CHECK(length(payload_hash)=64), provider TEXT NOT NULL, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
INSERT INTO schema_migrations VALUES(2,'2026-09-24T00:00:00.000Z');
COMMIT;
